(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-099"]={"sura":99,"name_ar":"الزلزلة","name_en":"Az-Zalzalah","verses":8,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":8,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=99&ayah=8\" class=\"link\">99:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 99:8 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=99&ayah=8\" class=\"link\">99:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 99:8 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=99&ayah=8\" class=\"link\">99:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 99:8 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=99&ayah=8\" class=\"link\">99:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 99:8 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=99&ayah=8\" class=\"link\">99:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 99:8 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=99&ayah=8\" class=\"link\">99:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 99:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=99&ayah=8\" class=\"link\">99:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 99:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<strong>சூரா அஸ்-ஸல்ஸலாவின் சிறப்புகள்</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: \"ஒரு மனிதர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நான் ஓதுவதற்கு ஏதேனும் கற்றுக் கொடுங்கள்!' என்று வேண்டினார்கள்.\" நபி (ஸல்) அவர்கள், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">اقْرَأْ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثًا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذَوَاتِ</span> <span class=\"quran-arabic-font text-success\">الر</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('அலிஃப், லாம், ரா' எனத் தொடங்கும் சூராக்களில் மூன்றை ஓதுவீராக) என்று கூறினார்கள். அதற்கு அந்த மனிதர், 'எனக்கு வயதாகிவிட்டது, என் இதயம் கடினமாகிவிட்டது, என் நாவும் தடினமாகிவிட்டது' என்று கூறினார்கள். நபி (ஸல்) அவர்கள், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">فَاقْرَأْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذَوَاتِ</span> <span class=\"quran-arabic-font text-success\">حم</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('ஹா-மீம்' எனத் தொடங்கும் சூராக்களில் இருந்து ஓதுவீராக) என்று கூறினார்கள். அந்த மனிதர் மீண்டும் முன்பே கூறியது போலவே கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">اقْرَأْ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثًا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسَبِّحَات</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('முஸப்பிஹாத்' சூராக்களில் மூன்றை ஓதுவீராக) என்று கூறினார்கள். அந்த மனிதர் மீண்டும் அதே பதிலைக் கூறினார்கள். பிறகு அந்த மனிதர், 'அல்லாஹ்வின் தூதரே! (இவை அனைத்தையும்) உள்ளடக்கிய ஒரு விரிவான சூராவை எனக்குக் கற்றுக்கொடுங்கள்' என்று வேண்டினார்கள். எனவே, நபி (ஸல்) அவர்கள் அவருக்கு, <span class=\"quran-arabic-font text-success\">﴾إِذَا</span> <span class=\"quran-arabic-font text-success\">زُلْزِلَتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">زِلْزَالَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('பூமி அதன் அதிர்வால் அதிர்வூட்டப்படும்போது' என்ற சூராவை) ஓதுமாறு கூறினார்கள். நபி (ஸல்) அவர்கள் அந்த சூராவை அவருக்கு ஓதிக்காட்டி முடித்ததும், அந்த மனிதர், 'உங்களை சத்தியத்துடன் இறைத்தூதராக அனுப்பியவன் மீது சத்தியமாக! இதில் நான் எதையும் கூட்டவோ குறைக்கவோ மாட்டேன்' என்று கூறிவிட்டுத் திரும்பினார்கள். அப்போது நபி (ஸல்) அவர்கள், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">الرُّوَيْجِلُ،</span> <span class=\"quran-arabic-font text-success\">أَفْلَحَ</span> <span class=\"quran-arabic-font text-success\">الرُّوَيْجِل</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('அந்தச் சிறிய மனிதர் வெற்றி பெற்றுவிட்டார், அந்தச் சிறிய மனிதர் வெற்றி பெற்றுவிட்டார்') என்று கூறினார்கள். பிறகு நபி (ஸல்) அவர்கள், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">عَلَيَّ</span> <span class=\"quran-arabic-font text-success\">بِه</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('அவரை என்னிடம் மீண்டும் அழைத்து வாருங்கள்') என்று கூறினார்கள். அந்த மனிதர் வந்ததும் நபி (ஸல்) அவர்கள் அவரிடம், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">أُمِرْتُ</span> <span class=\"quran-arabic-font text-success\">بِيَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْأَضْحَى</span> <span class=\"quran-arabic-font text-success\">جَعَلَهُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">عِيدًا</span> <span class=\"quran-arabic-font text-success\">لِهَذِهِ</span> <span class=\"quran-arabic-font text-success\">الْأُمَّة</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('ஈதுல் அழ்ஹா நாளைக் கொண்டாடுமாறும் நான் கட்டளையிடப்பட்டுள்ளேன்; அதை அல்லாஹ் இந்த உம்மத்திற்கு ஒரு பெருநாளாக ஆக்கியுள்ளான்') என்று கூறினார்கள். அந்த மனிதர், 'என்னிடத்தில் கறவைக்காக இரவலாகப் பெறப்பட்ட ஒரு பெண் ஒட்டகம் மட்டுமே இருந்தால், அதை நான் குர்பானி கொடுக்கலாமா?' என்று கேட்டார்கள். நபி (ஸல்) அவர்கள், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنَّكَ</span> <span class=\"quran-arabic-font text-success\">تَأْخُذُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">شَعْرِكَ</span> <span class=\"quran-arabic-font text-success\">وَتُقَلِّمُ</span> <span class=\"quran-arabic-font text-success\">أَظَافِرَكَ</span> <span class=\"quran-arabic-font text-success\">وَتَقُصُّ</span> <span class=\"quran-arabic-font text-success\">شَارِبَكَ</span> <span class=\"quran-arabic-font text-success\">وَتَحْلِقُ</span> <span class=\"quran-arabic-font text-success\">عَانَتَكَ</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">تَمَامُ</span> <span class=\"quran-arabic-font text-success\">أُضْحِيَّتِكَ</span> <span class=\"quran-arabic-font text-success\">عِنْدَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَل</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('இல்லை. மாறாக, உமது தலைமுடியைக் களைந்து, நகங்களை வெட்டி, மீசையைக் கத்தரித்து, மறைவிட ரோமங்களை மழித்துக் கொள்வீராக. அதுவே சர்வ வல்லமையும் மாண்பும் மிக்க அல்லாஹ்விடம் உமது குர்பானி முழுமையடைந்ததாகக் கருதப்படும்') என்று கூறினார்கள்.\" அபூ தாவூத் மற்றும் அன்-நஸாயீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். <span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>மறுமை நாள் - அதில் நிகழப்போகும் நிகழ்வுகள், பூமியின் நிலை மற்றும் மக்களின் நிலை</strong><br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِذَا</span> <span class=\"quran-arabic-font text-success\">زُلْزِلَتِ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">زِلْزَالَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமி அதன் அதிர்வால் அதிர்வூட்டப்படும்போது.) \"இதன் பொருள், பூமி அதன் கீழிருந்து அசைக்கப்படும் என்பதாகும்.\" <span class=\"quran-arabic-font text-success\">﴾وَأَخْرَجَتِ</span> <span class=\"quran-arabic-font text-success\">الأَرْضُ</span> <span class=\"quran-arabic-font text-success\">أَثْقَالَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமி தன் சுமைகளை வெளியேற்றும் போது.) அதாவது, பூமியினுள் புதைந்துள்ள மரணித்தவர்களை அது வெளியே தள்ளும். ஸலஃபுகளில் பலர் இவ்வாறு கூறியுள்ளனர். இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">اتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">زَلْزَلَةَ</span> <span class=\"quran-arabic-font text-success\">السَّاعَةِ</span> <span class=\"quran-arabic-font text-success\">شَىْءٌ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மக்களே! உங்கள் இறைவனுக்கு அஞ்சி (தக்வாவுடன்) நடங்கள்! நிச்சயமாக மறுமை நேரத்தின் அந்த நிலநடுக்கம் (ஸல்ஸலா) ஒரு பயங்கரமான விஷயமாகும்.) (<a href=\"qurandisp.php?sura=22&ayah=1\" class=\"link\">22:1</a>). இது அவனது மற்றொரு வசனத்தையும் ஒத்திருக்கிறது: <span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">مُدَّتْ</span> - <span class=\"quran-arabic-font text-success\">وَأَلْقَتْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">وَتَخَلَّتْ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமி விரிக்கப்பட்டு, அதனுள் உள்ளவற்றை வெளியே எறிந்துவிட்டு அது காலியாகும்போது.) (<a href=\"qurandisp.php?sura=84&ayah=3\" class=\"link\">84:3</a>-4). இமாம் முஸ்லிம் அவர்கள் தனது ஸஹீஹில் அபூ ஹுரைரா (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">تُلْقِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضُ</span> <span class=\"quran-arabic-font text-success\">أَفْلَاذَ</span> <span class=\"quran-arabic-font text-success\">كَبِدِهَا</span> <span class=\"quran-arabic-font text-success\">أَمْثَالَ</span> <span class=\"quran-arabic-font text-success\">الْأُسْطُوَانِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الذَّهَبِ</span> <span class=\"quran-arabic-font text-success\">وَالْفِضَّةِ،</span> <span class=\"quran-arabic-font text-success\">فَيَجِيءُ</span> <span class=\"quran-arabic-font text-success\">الْقَاتِلُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">قَتَلْتُ،</span> <span class=\"quran-arabic-font text-success\">وَيَجِيءُ</span> <span class=\"quran-arabic-font text-success\">الْقَاطِعُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">قَطَعْتُ</span> <span class=\"quran-arabic-font text-success\">رَحِمِي،وَيَجِيءُ</span> <span class=\"quran-arabic-font text-success\">السَّارِقُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">قُطِعَتْ</span> <span class=\"quran-arabic-font text-success\">يَدِي،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَدَعُونَهُ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">يَأْخُذُونَ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமி தனது ஈரல் துண்டுகளை (தன்னுள்ளே புதைந்துள்ளவற்றை) தங்கம் மற்றும் வெள்ளியாலான தூண்களைப் போல வெளியே தள்ளும். அப்போது ஒரு கொலையாளி வந்து, 'இதற்காகவா நான் ஒருவரைக் கொலை செய்தேன்?' என்று கேட்பான். உறவுகளைத் துண்டித்தவன் வந்து, 'இதற்காகவா நான் இரத்த உறவுகளை முறித்தேன்?' என்பான். திருடன் வந்து, 'இதற்காகவா எனது கை துண்டிக்கப்பட்டது?' என்பான். பிறகு மக்கள் அதனை அப்படியே விட்டுவிடுவார்கள்; அதிலிருந்து எதையும் யாரும் எடுத்துக்கொள்ள மாட்டார்கள்.)\" பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الإِنسَـنُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் மனிதன், \"அதற்கு என்ன நேர்ந்தது?\" என்று கேட்பான்.) அதாவது, எப்போதும் நிலையாகவும் உறுதியாகவும் இருந்த பூமி, இப்போது அதிர்ந்து நகர்வதைக் கண்டு அதன் மேற்பரப்பில் வாழ்ந்த மனிதன் திகைப்படைவான். அல்லாஹ் அதற்காக நிர்ணயித்த தவிர்க்க முடியாத அந்தப் பயங்கர நிலநடுக்கம் ஏற்படும். பிறகு அது ஆதி மனிதர் முதல் கடைசி மனிதர் வரை அனைத்து மரணித்தவர்களையும் வெளியே தள்ளும். அந்த நேரத்தில் நிகழும் மாற்றங்களையும், பூமி மற்றும் வானங்கள் வேறு கோலமாக மாறுவதையும் கண்டு மக்கள் அதிர்ச்சியடைவார்கள். பிறகு அவர்கள் தனித்தவனும், அடக்கியாள்பவனுமாகிய அல்லாஹ்விடம் ஆஜர்படுத்தப்படுவார்கள். அல்லாஹ்வின் இந்த வசனத்தைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">تُحَدِّثُ</span> <span class=\"quran-arabic-font text-success\">أَخْبَارَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில், அது தனது செய்திகளை அறிவிக்கும்.) அதாவது, பூமியின் மேற்பரப்பில் மக்கள் செய்த செயல்களைப் பற்றி அது பேசும். இமாம் அஹ்மத், அத்-திர்மிதீ மற்றும் அபூ அப்துர் ரஹ்மான் அன்-நஸாயீ ஆகியோர் அபூ ஹுரைரா (ரழி) அவர்கள் வழியாக ஒரு ஹதீஸைப் பதிவு செய்துள்ளனர். அன்-நஸாயீயின் பதிவில் உள்ளதாவது, அவர் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">تُحَدِّثُ</span> <span class=\"quran-arabic-font text-success\">أَخْبَارَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில், அது தனது செய்திகளை அறிவிக்கும்.) பிறகு அவர்கள், <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">أَتَدْرُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَخْبَارُهَا؟</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('அதன் செய்திகள் என்னவென்று உங்களுக்குத் தெரியுமா?') என்று கேட்டார்கள். அதற்கு அவர்கள், 'அல்லாஹ்வும் அவனது தூதருமே நன்கு அறிந்தவர்கள்' என்று கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">أَخْبَارَهَا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَشْهَدَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">عَبْدٍ</span> <span class=\"quran-arabic-font text-success\">وَأَمَةٍ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ظَهْرِهَا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَقُولَ</span>: <span class=\"quran-arabic-font text-success\">عَمِلَ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا،</span> <span class=\"quran-arabic-font text-success\">فَهَذِهِ</span> <span class=\"quran-arabic-font text-success\">أَخْبَارُهَا</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('நிச்சயமாக அதன் செய்தி என்னவென்றால், அது ஒவ்வொரு ஆண் மற்றும் பெண் அடியாரும் அதன் மேற்பரப்பில் செய்த செயல்களைப் பற்றி சாட்சியம் கூறுவதாகும். இன்னின்ன நாளில், இன்னின்ன காரியங்களை இவர் செய்தார் என்று அது கூறும். இதுவே அதன் செய்தியாகும்.')\" பிறகு இமாம் அத்-திர்மிதீ அவர்கள், 'இந்த ஹதீஸ் ஸஹீஹ் ஃகரீப்' என்று குறிப்பிட்டுள்ளார். அல்லாஹ்வின் வசனத்தைப் பற்றி: <span class=\"quran-arabic-font text-success\">﴾بِأَنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">أَوْحَى</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஏனெனில், உமது இறைவன் அதற்கு வஹீ (இறைச்செய்தி) அறிவித்ததனால்.) இதன் வெளிப்படையான பொருள் யாதெனில், அல்லாஹ் பூமிக்குப் பேசுவதற்கு அனுமதி அளிப்பான் என்பதாகும். ஷபீப் பின் பிஷ்ர் அவர்கள் இக்ரிமா (ரழி) வழியாக, இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">تُحَدِّثُ</span> <span class=\"quran-arabic-font text-success\">أَخْبَارَهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில், அது தனது செய்திகளை அறிவிக்கும்.) \"அதன் இறைவன் அதனிடம் 'பேசு' என்று கூறுவான், உடனே அது பேசும்.\" முஜாஹித் அவர்கள் (\"வஹீ அறிவித்ததனால்\" என்பதற்கு) 'அவன் அதற்கு கட்டளையிடுகிறான்' என்று விளக்கமளித்தார்கள். அல்-குரழீ அவர்கள், 'அவன் மக்களிடமிருந்து விலகிச் செல்லுமாறு பூமிக்குக் கட்டளையிடுவான்' என்று கூறினார்கள். பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَصْدُرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">أَشْتَاتاً﴿</span><br />\r\n<br />\r\n(அந்நாளில், மக்கள் வெவ்வேறு குழுக்களாக (அஷ்தாத்) திரும்புவார்கள்.) அதாவது, விசாரணை மைதானத்திலிருந்து அவர்கள் வெவ்வேறு பிரிவுகளாகப் பிரிந்து செல்வார்கள். துரதிர்ஷ்டசாலிகள், பாக்கியசாலிகள், சொர்க்கத்திற்குச் செல்லுமாறு ஏவப்பட்டவர்கள், நரகத்திற்குச் செல்லுமாறு ஏவப்பட்டவர்கள் என அவர்கள் பிரிக்கப்படுவார்கள். அஸ்-ஸுத்தீ அவர்கள், 'அஷ்தாத் என்றால் பிரிவுகள்' என்று விளக்கமளித்தார்கள். அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾لِّيُرَوْاْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلَهُمْ﴿</span><br />\r\n<br />\r\n(அவர்களுடைய செயல்கள் அவர்களுக்குக் காட்டப்படுவதற்காக.) அதாவது, இவ்வுலகில் அவர்கள் செய்த நன்மை மற்றும் தீமைகளுக்கான பிரதிபலனை அவர்கள் காண்பதற்காக.<br />\r\n<br />\r\n<strong>ஒவ்வொரு சிறிய செயலுக்குமான பிரதிபலன்</strong><br />\r\n<br />\r\nஅல்லாஹ் மேலும் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">يَرَهُ</span> - <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْـمَلْ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">شَرّاً</span> <span class=\"quran-arabic-font text-success\">يَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே, எவர் ஓர் அணுவளவு நன்மை செய்திருந்தாலும் அதைக் காண்பார். மேலும் எவர் ஓர் அணுவளவு தீமை செய்திருந்தாலும் அதையும் அவர் காண்பார்.) இமாம் புகாரீ அவர்கள் அபூ ஹுரைரா (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">الْخَيْلُ</span> <span class=\"quran-arabic-font text-success\">لِثَلَاثَةٍ،</span> <span class=\"quran-arabic-font text-success\">لِرَجُلٍ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ،</span> <span class=\"quran-arabic-font text-success\">وَلِرَجُلٍ</span> <span class=\"quran-arabic-font text-success\">سِتْرٌ،</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">رَجُلٍ</span> <span class=\"quran-arabic-font text-success\">وِزْرٌ</span>. <span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ</span> <span class=\"quran-arabic-font text-success\">فَرَجُلٌ</span> <span class=\"quran-arabic-font text-success\">رَبَطَهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">فَأَطَالَ</span> <span class=\"quran-arabic-font text-success\">طِيَلَهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مَرْجٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">رَوْضَةٍ،</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">أَصَابَتْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">طِيَلِهَا</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْمَرْجِ</span> <span class=\"quran-arabic-font text-success\">وَالرَّوْضَةِ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">حَسَنَاتٍ،</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهَا</span> <span class=\"quran-arabic-font text-success\">قَطَعَتْ</span> <span class=\"quran-arabic-font text-success\">طِيَلَهَا</span> <span class=\"quran-arabic-font text-success\">فَاسْتَنَّتْ</span> <span class=\"quran-arabic-font text-success\">شَرَفًا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">شَرَفَيْنِ</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">آثَارُهَا</span> <span class=\"quran-arabic-font text-success\">وَأَرْوَاثُهَا</span> <span class=\"quran-arabic-font text-success\">حَسَنَاتٍ</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهَا</span> <span class=\"quran-arabic-font text-success\">مَرَّتْ</span> <span class=\"quran-arabic-font text-success\">بِنَهَرٍ</span> <span class=\"quran-arabic-font text-success\">فَشَرِبَتْ</span> <span class=\"quran-arabic-font text-success\">مِنْه</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يُرِدْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَسْقِيَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">حَسَنَاتٍ</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">وَهِيَ</span> <span class=\"quran-arabic-font text-success\">لِذَلِكَ</span> <span class=\"quran-arabic-font text-success\">الرَّجُلِ</span> <span class=\"quran-arabic-font text-success\">أَجْرٌ</span>. <span class=\"quran-arabic-font text-success\">وَرَجُلٌ</span> <span class=\"quran-arabic-font text-success\">رَبَطَهَا</span> <span class=\"quran-arabic-font text-success\">تَغَنِّـيًا</span> <span class=\"quran-arabic-font text-success\">وَتَعَفُّفًا</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَنْسَ</span> <span class=\"quran-arabic-font text-success\">حَقَّ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">رِقَابِهَا</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">ظُهُورِهَا</span> <span class=\"quran-arabic-font text-success\">فَهِيَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">سِتْرٌ،</span> <span class=\"quran-arabic-font text-success\">وَرَجُلٌ</span> <span class=\"quran-arabic-font text-success\">رَبَطَها</span> <span class=\"quran-arabic-font text-success\">فَخْرًا</span> <span class=\"quran-arabic-font text-success\">وَرِيَاءً</span> <span class=\"quran-arabic-font text-success\">وَنِوَاءً</span> <span class=\"quran-arabic-font text-success\">فَهِيَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وِزْر</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(குதிரைகள் மூன்று வகைப்படும்: ஒரு மனிதருக்கு அது நற்கூலி, மற்றொருவருக்கு அது ஒரு பாதுகாப்பு (திரை), இன்னொருவருக்கு அது சுமையாகும். யாருக்கு அது நற்கூலியோ, அவர் அதனை அல்லாஹ்வின் பாதையில் (அறப்போருக்காக) பயன்படுத்துவதற்காகக் கட்டி வளர்ப்பவர். அது புல்வெளியிலோ அல்லது ஒரு தோட்டத்திலோ மேய்வதற்காகக் கட்டப்பட்டிருக்கும் காலத்தில், அந்தப் புல்வெளியில் அது எவற்றையெல்லாம் உண்ணுகிறதோ அவை யாவும் அவருக்கு நன்மைகளாக எழுதப்படும். மேலும் அது தனது கயிற்றை அறுத்துக்கொண்டு ஒரு மேட்டுப் பகுதியையோ அல்லது இரு மேட்டுப் பகுதிகளையோ கடந்தால், அதன் குளம்படித் தடங்களும் அதன் சாணமும் கூட அவருக்கு நன்மைகளாகக் கணக்கிடப்படும். <br />\r\n<br />\r\nமேலும் அதன் உரிமையாளர் அதற்குத் தண்ணீர் புகட்ட எண்ணாத நிலையில், அது தானாகவே ஒரு ஆற்றைக் கடந்து அதிலிருந்து தண்ணீர் குடித்தாலும் கூட, அதுவும் அவருக்கு நன்மைகளாக எழுதப்படும். எனவே, அந்தக் குதிரை அவருக்கு நற்கூலியாகும். எவர் தனது சுயத் தேவையைப் பூர்த்தி செய்து கொள்ளவும், பிறரிடம் கையேந்தாமல் இருப்பதற்காகவும் அதனை வளர்க்கிறாரோ, மேலும் அதன் கழுத்து மற்றும் முதுகின் மீதுள்ள அல்லாஹ்வின் உரிமையை (ஸகாத் போன்றவற்றை) அவர் மறக்கவில்லையோ, அது அவருக்கு (வறுமை மற்றும் நரக நெருப்பிலிருந்து) பாதுகாப்பாக அமையும். எவர் தற்பெருமைக்காகவும், பிறருக்குக் காட்டுவதற்காகவும், பகைமை பாராட்டுவதற்காகவும் அதனை வளர்க்கிறாரோ, அது அவருக்குப் பாவச் சுமையாகும்.) பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கழுதைகளைப் பற்றிக் கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَنْزَلَ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">هَذِهِ</span> <span class=\"quran-arabic-font text-success\">الْآيَةَ</span> <span class=\"quran-arabic-font text-success\">الْفَاذَّةَ</span> <span class=\"quran-arabic-font text-success\">الْجَامِعَةَ﴿﴾فَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">يَرَهُ</span> - <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْـمَلْ</span> <span class=\"quran-arabic-font text-success\">مِثْقَالَ</span> <span class=\"quran-arabic-font text-success\">ذَرَّةٍ</span> <span class=\"quran-arabic-font text-success\">شَرّاً</span> <span class=\"quran-arabic-font text-success\">يَرَهُ</span> <span class=\"quran-arabic-font text-success\">﴿﴾</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(கழுதைகளைப் பற்றி அல்லாஹ் இந்தத் தனித்துவமான, முழுமையான வசனத்தைத் தவிர வேறெதையும் எனக்கு அருளவில்லை: (எனவே, எவர் ஓர் அணுவளவு நன்மை செய்திருந்தாலும் அதைக் காண்பார். மேலும் எவர் ஓர் அணுவளவு தீமை செய்திருந்தாலும் அதையும் அவர் காண்பார்.)) இமாம் முஸ்லிமும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார். ஸஹீஹ் புகாரீயில் அதீ (ரழி) அவர்கள் அறிவிக்கிறார்கள்; நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">اتَّــقُوا</span> <span class=\"quran-arabic-font text-success\">النَّارَ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">بِشِقِّ</span> <span class=\"quran-arabic-font text-success\">تَمْرَةٍ،</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">بِكَلِمَةٍ</span> <span class=\"quran-arabic-font text-success\">طَيِّـبَة</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஒரு பேரீச்சம் பழத்தின் ஒரு துண்டை தர்மம் செய்தாவது நரக நெருப்பிலிருந்து உங்களைக் காத்துக் கொள்ளுங்கள்; அதுவும் இல்லையெனில் ஒரு நல்ல சொல்லின் மூலமாவது தற்காத்துக் கொள்ளுங்கள்.) மேலும் அதே ஸஹீஹில் அதீ (ரழி) அவர்கள் அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَحْقِرَنَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَعْرُوفِ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تُفْرِغَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">دَلْوِكَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">إِنَاءِ</span> <span class=\"quran-arabic-font text-success\">الْمُسْتَسْقِي،</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَلْقَى</span> <span class=\"quran-arabic-font text-success\">أَخَاكَ</span> <span class=\"quran-arabic-font text-success\">وَوَجْهُكَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مُنْـبَسِط</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எந்த ஒரு நற்செயலையும் அற்பமாகக் கருதாதீர்கள். தாகித்திருப்பவரின் பாத்திரத்தில் உமது வாளியிலிருந்து ஒரு முகவை தண்ணீரை ஊற்றுவதாக இருந்தாலும் சரி, அல்லது உமது சகோதரரை மலர்ந்த முகத்துடன் சந்திப்பதாக இருந்தாலும் சரி.) ஸஹீஹில் மேலும் ஒரு ஹதீஸ் பதிவாகியுள்ளது; நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مَعْشَرَ</span> <span class=\"quran-arabic-font text-success\">نِسَاءِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنَاتِ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَحْقِرَنَّ</span> <span class=\"quran-arabic-font text-success\">جَارَةٌ</span> <span class=\"quran-arabic-font text-success\">لِجَارَتِهَا</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">فِرْسَنَ</span> <span class=\"quran-arabic-font text-success\">شَاة</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(விசுவாசமுள்ள பெண்களே! உங்களில் எவரும் தனது அண்டை வீட்டுப் பெண்ணிற்குக் கொடுப்பதை, அது ஓர் ஆட்டின் குளம்பாக இருந்தாலும் அதனை அற்பமாகக் கருத வேண்டாம்.) 'ஃபிர்ஸன்' என்பது ஆட்டின் குளம்பைக் குறிக்கும். மற்றொரு ஹதீஸில் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">رُدُّوا</span> <span class=\"quran-arabic-font text-success\">السَّائِلَ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">بِظِلْفٍ</span> <span class=\"quran-arabic-font text-success\">مُحْرَق</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(கேட்பவருக்கு ஏதேனும் கொடுங்கள், அது கருகிய குளம்பாக இருந்தாலும் சரி.) ஆயிஷா (ரழி) அவர்கள் ஒரு திராட்சைப் பழத்தைத் தர்மமாக வழங்கியபோது, \"இது எத்தனை அணுக்களுக்குச் சமமானது தெரியுமா?\" என்று கேட்டதாக அறிவிக்கப்பட்டுள்ளது. இமாம் அஹ்மத் அவர்கள் அவ்ஃப் பின் அல்-ஹாரித் பின் அத்-துஃபைல் வழியாக அறிவிக்கிறார்கள்; ஆயிஷா (ரழி) அவர்கள் கூறியுள்ளார்கள், நபி (ஸல்) அவர்கள் இவ்வாறு கூறுவதுண்டு: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يَاعَائِشَةُ،</span> <span class=\"quran-arabic-font text-success\">إِيَّاكِ</span> <span class=\"quran-arabic-font text-success\">وَمُحَقَّرَاتِ</span> <span class=\"quran-arabic-font text-success\">الذُّنُوبِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">طَالِبًا</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆயிஷாவே! அற்பமாகக் கருதப்படும் பாவங்களைக் குறித்து எச்சரிக்கையாக இருங்கள். ஏனெனில், நிச்சயமாக அவற்றைப் பற்றியும் அல்லாஹ்விடம் விசாரணை உண்டு.) இந்த ஹதீஸை அன்-நஸாயீ மற்றும் இப்னு மாஜா ஆகியோரும் பதிவு செய்துள்ளனர். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَمُحَقَّرَاتِ</span> <span class=\"quran-arabic-font text-success\">الذُّنُوبِ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُنَّ</span> <span class=\"quran-arabic-font text-success\">يَجْتَمِعْنَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الرَّجُلِ</span> <span class=\"quran-arabic-font text-success\">حَتْى</span> <span class=\"quran-arabic-font text-success\">يُهْلِكْنَه</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அற்பமாகக் கருதப்படும் பாவங்களைக் குறித்து எச்சரிக்கையாக இருங்கள். ஏனெனில், அவை ஒரு மனிதனிடம் ஒன்று சேர்ந்து அவனைக் கருவறுத்துவிடும்.) இத்தகைய சிறு பாவங்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஓர் உதாரணமாகக் கூறினார்கள்: வறண்ட நிலத்தில் தங்கும் ஒரு கூட்டத்தைப் போல, அவர்கள் ஒவ்வொருவராகச் சென்று சிறு குச்சிகளைக் கொண்டு வந்து பெரிய சுள்ளிக் குவியலைச் சேர்க்கின்றனர். பிறகு அவர்கள் அதைக் கொண்டு நெருப்பை மூட்டி, அதில் எதைப் போட்டார்களோ அதைச் சமைத்துக் கொள்கிறார்கள். இது சூரா அஸ்-ஸல்ஸலாவின் தஃப்ஸீரின் நிறைவாகும். எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"மதீனாவில் அருளப்பட்டது\n\r\n\n\r\nசூரா அஸ்-ஸல்ஸலாவின் சிறப்புகள்\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்கள்: \"ஒரு மனிதர் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்து, 'அல்லாஹ்வின் தூதரே! நான் ஓதுவதற்கு ஏதேனும் கற்றுக் கொடுங்கள்!' என்று வேண்டினார்கள்.\" நபி (ஸல்) அவர்கள், ﴾«اقْرَأْ ثَلَاثًا مِنْ ذَوَاتِ الر»﴿\n\r\n\n\r\n('அலிஃப், லாம், ரா' எனத் தொடங்கும் சூராக்களில் மூன்றை ஓதுவீராக) என்று கூறினார்கள். அதற்கு அந்த மனிதர், 'எனக்கு வயதாகிவிட்டது, என் இதயம் கடினமாகிவிட்டது, என் நாவும் தடினமாகிவிட்டது' என்று கூறினார்கள். நபி (ஸல்) அவர்கள், ﴾«فَاقْرَأْ مِنْ ذَوَاتِ حم»﴿\n\r\n\n\r\n('ஹா-மீம்' எனத் தொடங்கும் சூராக்களில் இருந்து ஓதுவீராக) என்று கூறினார்கள். அந்த மனிதர் மீண்டும் முன்பே கூறியது போலவே கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள், ﴾«اقْرَأْ ثَلَاثًا مِنَ الْمُسَبِّحَات»﴿\n\r\n\n\r\n('முஸப்பிஹாத்' சூராக்களில் மூன்றை ஓதுவீராக) என்று கூறினார்கள். அந்த மனிதர் மீண்டும் அதே பதிலைக் கூறினார்கள். பிறகு அந்த மனிதர், 'அல்லாஹ்வின் தூதரே! (இவை அனைத்தையும்) உள்ளடக்கிய ஒரு விரிவான சூராவை எனக்குக் கற்றுக்கொடுங்கள்' என்று வேண்டினார்கள். எனவே, நபி (ஸல்) அவர்கள் அவருக்கு, ﴾إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا ﴿\n\r\n\n\r\n('பூமி அதன் அதிர்வால் அதிர்வூட்டப்படும்போது' என்ற சூராவை) ஓதுமாறு கூறினார்கள். நபி (ஸல்) அவர்கள் அந்த சூராவை அவருக்கு ஓதிக்காட்டி முடித்ததும், அந்த மனிதர், 'உங்களை சத்தியத்துடன் இறைத்தூதராக அனுப்பியவன் மீது சத்தியமாக! இதில் நான் எதையும் கூட்டவோ குறைக்கவோ மாட்டேன்' என்று கூறிவிட்டுத் திரும்பினார்கள். அப்போது நபி (ஸல்) அவர்கள், ﴾«أَفْلَحَ الرُّوَيْجِلُ، أَفْلَحَ الرُّوَيْجِل»﴿\n\r\n\n\r\n('அந்தச் சிறிய மனிதர் வெற்றி பெற்றுவிட்டார், அந்தச் சிறிய மனிதர் வெற்றி பெற்றுவிட்டார்') என்று கூறினார்கள். பிறகு நபி (ஸல்) அவர்கள், ﴾«عَلَيَّ بِه»﴿\n\r\n\n\r\n('அவரை என்னிடம் மீண்டும் அழைத்து வாருங்கள்') என்று கூறினார்கள். அந்த மனிதர் வந்ததும் நபி (ஸல்) அவர்கள் அவரிடம், ﴾«أُمِرْتُ بِيَوْمِ الْأَضْحَى جَعَلَهُ اللهُ عِيدًا لِهَذِهِ الْأُمَّة»﴿\n\r\n\n\r\n('ஈதுல் அழ்ஹா நாளைக் கொண்டாடுமாறும் நான் கட்டளையிடப்பட்டுள்ளேன்; அதை அல்லாஹ் இந்த உம்மத்திற்கு ஒரு பெருநாளாக ஆக்கியுள்ளான்') என்று கூறினார்கள். அந்த மனிதர், 'என்னிடத்தில் கறவைக்காக இரவலாகப் பெறப்பட்ட ஒரு பெண் ஒட்டகம் மட்டுமே இருந்தால், அதை நான் குர்பானி கொடுக்கலாமா?' என்று கேட்டார்கள். நபி (ஸல்) அவர்கள், ﴾«لَا، وَلَكِنَّكَ تَأْخُذُ مِنْ شَعْرِكَ وَتُقَلِّمُ أَظَافِرَكَ وَتَقُصُّ شَارِبَكَ وَتَحْلِقُ عَانَتَكَ فَذَاكَ تَمَامُ أُضْحِيَّتِكَ عِنْدَ اللهِ عَزَّ وَجَل»﴿\n\r\n\n\r\n('இல்லை. மாறாக, உமது தலைமுடியைக் களைந்து, நகங்களை வெட்டி, மீசையைக் கத்தரித்து, மறைவிட ரோமங்களை மழித்துக் கொள்வீராக. அதுவே சர்வ வல்லமையும் மாண்பும் மிக்க அல்லாஹ்விடம் உமது குர்பானி முழுமையடைந்ததாகக் கருதப்படும்') என்று கூறினார்கள்.\" அபூ தாவூத் மற்றும் அன்-நஸாயீ ஆகியோரும் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர். ﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nமறுமை நாள் - அதில் நிகழப்போகும் நிகழ்வுகள், பூமியின் நிலை மற்றும் மக்களின் நிலை\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: ﴾إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا ﴿\n\r\n\n\r\n(பூமி அதன் அதிர்வால் அதிர்வூட்டப்படும்போது.) \"இதன் பொருள், பூமி அதன் கீழிருந்து அசைக்கப்படும் என்பதாகும்.\" ﴾وَأَخْرَجَتِ الأَرْضُ أَثْقَالَهَا ﴿\n\r\n\n\r\n(பூமி தன் சுமைகளை வெளியேற்றும் போது.) அதாவது, பூமியினுள் புதைந்துள்ள மரணித்தவர்களை அது வெளியே தள்ளும். ஸலஃபுகளில் பலர் இவ்வாறு கூறியுள்ளனர். இது அல்லாஹ்வின் பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾يأَيُّهَا النَّاسُ اتَّقُواْ رَبَّكُمْ إِنَّ زَلْزَلَةَ السَّاعَةِ شَىْءٌ عَظِيمٌ ﴿\n\r\n\n\r\n(மக்களே! உங்கள் இறைவனுக்கு அஞ்சி (தக்வாவுடன்) நடங்கள்! நிச்சயமாக மறுமை நேரத்தின் அந்த நிலநடுக்கம் (ஸல்ஸலா) ஒரு பயங்கரமான விஷயமாகும்.) (22:1). இது அவனது மற்றொரு வசனத்தையும் ஒத்திருக்கிறது: ﴾وَإِذَا الْأَرْضُ مُدَّتْ - وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ ﴿\n\r\n\n\r\n(பூமி விரிக்கப்பட்டு, அதனுள் உள்ளவற்றை வெளியே எறிந்துவிட்டு அது காலியாகும்போது.) (84:3-4). இமாம் முஸ்லிம் அவர்கள் தனது ஸஹீஹில் அபூ ஹுரைரா (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: ﴾«تُلْقِي الْأَرْضُ أَفْلَاذَ كَبِدِهَا أَمْثَالَ الْأُسْطُوَانِ مِنَ الذَّهَبِ وَالْفِضَّةِ، فَيَجِيءُ الْقَاتِلُ فَيَقُولُ فِي هَذَا قَتَلْتُ، وَيَجِيءُ الْقَاطِعُ فَيَقُولُ فِي هَذَا قَطَعْتُ رَحِمِي،وَيَجِيءُ السَّارِقُ فَيَقُولُ: فِي هَذَا قُطِعَتْ يَدِي، ثُمَّ يَدَعُونَهُ فَلَا يَأْخُذُونَ مِنْهُ شَيْئًا»﴿\n\r\n\n\r\n(பூமி தனது ஈரல் துண்டுகளை (தன்னுள்ளே புதைந்துள்ளவற்றை) தங்கம் மற்றும் வெள்ளியாலான தூண்களைப் போல வெளியே தள்ளும். அப்போது ஒரு கொலையாளி வந்து, 'இதற்காகவா நான் ஒருவரைக் கொலை செய்தேன்?' என்று கேட்பான். உறவுகளைத் துண்டித்தவன் வந்து, 'இதற்காகவா நான் இரத்த உறவுகளை முறித்தேன்?' என்பான். திருடன் வந்து, 'இதற்காகவா எனது கை துண்டிக்கப்பட்டது?' என்பான். பிறகு மக்கள் அதனை அப்படியே விட்டுவிடுவார்கள்; அதிலிருந்து எதையும் யாரும் எடுத்துக்கொள்ள மாட்டார்கள்.)\" பிறகு அல்லாஹ் கூறுகிறான்: ﴾وَقَالَ الإِنسَـنُ مَا لَهَا ﴿\n\r\n\n\r\n(மேலும் மனிதன், \"அதற்கு என்ன நேர்ந்தது?\" என்று கேட்பான்.) அதாவது, எப்போதும் நிலையாகவும் உறுதியாகவும் இருந்த பூமி, இப்போது அதிர்ந்து நகர்வதைக் கண்டு அதன் மேற்பரப்பில் வாழ்ந்த மனிதன் திகைப்படைவான். அல்லாஹ் அதற்காக நிர்ணயித்த தவிர்க்க முடியாத அந்தப் பயங்கர நிலநடுக்கம் ஏற்படும். பிறகு அது ஆதி மனிதர் முதல் கடைசி மனிதர் வரை அனைத்து மரணித்தவர்களையும் வெளியே தள்ளும். அந்த நேரத்தில் நிகழும் மாற்றங்களையும், பூமி மற்றும் வானங்கள் வேறு கோலமாக மாறுவதையும் கண்டு மக்கள் அதிர்ச்சியடைவார்கள். பிறகு அவர்கள் தனித்தவனும், அடக்கியாள்பவனுமாகிய அல்லாஹ்விடம் ஆஜர்படுத்தப்படுவார்கள். அல்லாஹ்வின் இந்த வசனத்தைப் பற்றி: ﴾يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ﴿\n\r\n\n\r\n(அந்நாளில், அது தனது செய்திகளை அறிவிக்கும்.) அதாவது, பூமியின் மேற்பரப்பில் மக்கள் செய்த செயல்களைப் பற்றி அது பேசும். இமாம் அஹ்மத், அத்-திர்மிதீ மற்றும் அபூ அப்துர் ரஹ்மான் அன்-நஸாயீ ஆகியோர் அபூ ஹுரைரா (ரழி) அவர்கள் வழியாக ஒரு ஹதீஸைப் பதிவு செய்துள்ளனர். அன்-நஸாயீயின் பதிவில் உள்ளதாவது, அவர் கூறினார்கள்: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இந்த வசனத்தை ஓதினார்கள்: ﴾يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ﴿\n\r\n\n\r\n(அந்நாளில், அது தனது செய்திகளை அறிவிக்கும்.) பிறகு அவர்கள், ﴾«أَتَدْرُونَ مَا أَخْبَارُهَا؟»﴿\n\r\n\n\r\n('அதன் செய்திகள் என்னவென்று உங்களுக்குத் தெரியுமா?') என்று கேட்டார்கள். அதற்கு அவர்கள், 'அல்லாஹ்வும் அவனது தூதருமே நன்கு அறிந்தவர்கள்' என்று கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«فَإِنَّ أَخْبَارَهَا أَنْ تَشْهَدَ عَلَى كُلِّ عَبْدٍ وَأَمَةٍ بِمَا عَمِلَ عَلَى ظَهْرِهَا أَنْ تَقُولَ: عَمِلَ كَذَا وَكَذَا يَوْمَ كَذَا وَكَذَا، فَهَذِهِ أَخْبَارُهَا»﴿\n\r\n\n\r\n('நிச்சயமாக அதன் செய்தி என்னவென்றால், அது ஒவ்வொரு ஆண் மற்றும் பெண் அடியாரும் அதன் மேற்பரப்பில் செய்த செயல்களைப் பற்றி சாட்சியம் கூறுவதாகும். இன்னின்ன நாளில், இன்னின்ன காரியங்களை இவர் செய்தார் என்று அது கூறும். இதுவே அதன் செய்தியாகும்.')\" பிறகு இமாம் அத்-திர்மிதீ அவர்கள், 'இந்த ஹதீஸ் ஸஹீஹ் ஃகரீப்' என்று குறிப்பிட்டுள்ளார். அல்லாஹ்வின் வசனத்தைப் பற்றி: ﴾بِأَنَّ رَبَّكَ أَوْحَى لَهَا ﴿\n\r\n\n\r\n(ஏனெனில், உமது இறைவன் அதற்கு வஹீ (இறைச்செய்தி) அறிவித்ததனால்.) இதன் வெளிப்படையான பொருள் யாதெனில், அல்லாஹ் பூமிக்குப் பேசுவதற்கு அனுமதி அளிப்பான் என்பதாகும். ஷபீப் பின் பிஷ்ர் அவர்கள் இக்ரிமா (ரழி) வழியாக, இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: ﴾يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ﴿\n\r\n\n\r\n(அந்நாளில், அது தனது செய்திகளை அறிவிக்கும்.) \"அதன் இறைவன் அதனிடம் 'பேசு' என்று கூறுவான், உடனே அது பேசும்.\" முஜாஹித் அவர்கள் (\"வஹீ அறிவித்ததனால்\" என்பதற்கு) 'அவன் அதற்கு கட்டளையிடுகிறான்' என்று விளக்கமளித்தார்கள். அல்-குரழீ அவர்கள், 'அவன் மக்களிடமிருந்து விலகிச் செல்லுமாறு பூமிக்குக் கட்டளையிடுவான்' என்று கூறினார்கள். பிறகு அல்லாஹ் கூறுகிறான்: ﴾يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتاً﴿\n\r\n\n\r\n(அந்நாளில், மக்கள் வெவ்வேறு குழுக்களாக (அஷ்தாத்) திரும்புவார்கள்.) அதாவது, விசாரணை மைதானத்திலிருந்து அவர்கள் வெவ்வேறு பிரிவுகளாகப் பிரிந்து செல்வார்கள். துரதிர்ஷ்டசாலிகள், பாக்கியசாலிகள், சொர்க்கத்திற்குச் செல்லுமாறு ஏவப்பட்டவர்கள், நரகத்திற்குச் செல்லுமாறு ஏவப்பட்டவர்கள் என அவர்கள் பிரிக்கப்படுவார்கள். அஸ்-ஸுத்தீ அவர்கள், 'அஷ்தாத் என்றால் பிரிவுகள்' என்று விளக்கமளித்தார்கள். அல்லாஹ் கூறினான்: ﴾لِّيُرَوْاْ أَعْمَـلَهُمْ﴿\n\r\n\n\r\n(அவர்களுடைய செயல்கள் அவர்களுக்குக் காட்டப்படுவதற்காக.) அதாவது, இவ்வுலகில் அவர்கள் செய்த நன்மை மற்றும் தீமைகளுக்கான பிரதிபலனை அவர்கள் காண்பதற்காக.\n\r\n\n\r\nஒவ்வொரு சிறிய செயலுக்குமான பிரதிபலன்\n\r\n\n\r\nஅல்லாஹ் மேலும் கூறுகிறான்: ﴾فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراً يَرَهُ - وَمَن يَعْـمَلْ مِثْقَالَ ذَرَّةٍ شَرّاً يَرَهُ ﴿\n\r\n\n\r\n(எனவே, எவர் ஓர் அணுவளவு நன்மை செய்திருந்தாலும் அதைக் காண்பார். மேலும் எவர் ஓர் அணுவளவு தீமை செய்திருந்தாலும் அதையும் அவர் காண்பார்.) இமாம் புகாரீ அவர்கள் அபூ ஹுரைரா (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: ﴾«الْخَيْلُ لِثَلَاثَةٍ، لِرَجُلٍ أَجْرٌ، وَلِرَجُلٍ سِتْرٌ، وَعَلَى رَجُلٍ وِزْرٌ. فَأَمَّا الَّذِي لَهُ أَجْرٌ فَرَجُلٌ رَبَطَهَا فِي سَبِيلِ اللهِ فَأَطَالَ طِيَلَهَا فِي مَرْجٍ أَوْ رَوْضَةٍ، فَمَا أَصَابَتْ فِي طِيَلِهَا ذَلِكَ فِي الْمَرْجِ وَالرَّوْضَةِ كَانَ لَهُ حَسَنَاتٍ، وَلَوْ أَنَّهَا قَطَعَتْ طِيَلَهَا فَاسْتَنَّتْ شَرَفًا أَوْ شَرَفَيْنِ كَانَتْ آثَارُهَا وَأَرْوَاثُهَا حَسَنَاتٍ لَهُ، وَلَوْ أَنَّهَا مَرَّتْ بِنَهَرٍ فَشَرِبَتْ مِنْه وَلَمْ يُرِدْ أَنْ يَسْقِيَ بِهِ كَانَ ذَلِكَ حَسَنَاتٍ لَهُ، وَهِيَ لِذَلِكَ الرَّجُلِ أَجْرٌ. وَرَجُلٌ رَبَطَهَا تَغَنِّـيًا وَتَعَفُّفًا وَلَمْ يَنْسَ حَقَّ اللهِ فِي رِقَابِهَا وَلَا ظُهُورِهَا فَهِيَ لَهُ سِتْرٌ، وَرَجُلٌ رَبَطَها فَخْرًا وَرِيَاءً وَنِوَاءً فَهِيَ عَلَى ذَلِكَ وِزْر»﴿\n\r\n\n\r\n(குதிரைகள் மூன்று வகைப்படும்: ஒரு மனிதருக்கு அது நற்கூலி, மற்றொருவருக்கு அது ஒரு பாதுகாப்பு (திரை), இன்னொருவருக்கு அது சுமையாகும். யாருக்கு அது நற்கூலியோ, அவர் அதனை அல்லாஹ்வின் பாதையில் (அறப்போருக்காக) பயன்படுத்துவதற்காகக் கட்டி வளர்ப்பவர். அது புல்வெளியிலோ அல்லது ஒரு தோட்டத்திலோ மேய்வதற்காகக் கட்டப்பட்டிருக்கும் காலத்தில், அந்தப் புல்வெளியில் அது எவற்றையெல்லாம் உண்ணுகிறதோ அவை யாவும் அவருக்கு நன்மைகளாக எழுதப்படும். மேலும் அது தனது கயிற்றை அறுத்துக்கொண்டு ஒரு மேட்டுப் பகுதியையோ அல்லது இரு மேட்டுப் பகுதிகளையோ கடந்தால், அதன் குளம்படித் தடங்களும் அதன் சாணமும் கூட அவருக்கு நன்மைகளாகக் கணக்கிடப்படும்.\n\r\n\n\r\nமேலும் அதன் உரிமையாளர் அதற்குத் தண்ணீர் புகட்ட எண்ணாத நிலையில், அது தானாகவே ஒரு ஆற்றைக் கடந்து அதிலிருந்து தண்ணீர் குடித்தாலும் கூட, அதுவும் அவருக்கு நன்மைகளாக எழுதப்படும். எனவே, அந்தக் குதிரை அவருக்கு நற்கூலியாகும். எவர் தனது சுயத் தேவையைப் பூர்த்தி செய்து கொள்ளவும், பிறரிடம் கையேந்தாமல் இருப்பதற்காகவும் அதனை வளர்க்கிறாரோ, மேலும் அதன் கழுத்து மற்றும் முதுகின் மீதுள்ள அல்லாஹ்வின் உரிமையை (ஸகாத் போன்றவற்றை) அவர் மறக்கவில்லையோ, அது அவருக்கு (வறுமை மற்றும் நரக நெருப்பிலிருந்து) பாதுகாப்பாக அமையும். எவர் தற்பெருமைக்காகவும், பிறருக்குக் காட்டுவதற்காகவும், பகைமை பாராட்டுவதற்காகவும் அதனை வளர்க்கிறாரோ, அது அவருக்குப் பாவச் சுமையாகும்.) பிறகு அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கழுதைகளைப் பற்றிக் கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்: ﴾«مَا أَنْزَلَ اللهُ فِيهَا شَيْئًا إِلَّا هَذِهِ الْآيَةَ الْفَاذَّةَ الْجَامِعَةَ﴿﴾فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْراً يَرَهُ - وَمَن يَعْـمَلْ مِثْقَالَ ذَرَّةٍ شَرّاً يَرَهُ ﴿﴾»﴿\n\r\n\n\r\n(கழுதைகளைப் பற்றி அல்லாஹ் இந்தத் தனித்துவமான, முழுமையான வசனத்தைத் தவிர வேறெதையும் எனக்கு அருளவில்லை: (எனவே, எவர் ஓர் அணுவளவு நன்மை செய்திருந்தாலும் அதைக் காண்பார். மேலும் எவர் ஓர் அணுவளவு தீமை செய்திருந்தாலும் அதையும் அவர் காண்பார்.)) இமாம் முஸ்லிமும் இந்த ஹதீஸைப் பதிவு செய்துள்ளார். ஸஹீஹ் புகாரீயில் அதீ (ரழி) அவர்கள் அறிவிக்கிறார்கள்; நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«اتَّــقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ، وَلَوْ بِكَلِمَةٍ طَيِّـبَة»﴿\n\r\n\n\r\n(ஒரு பேரீச்சம் பழத்தின் ஒரு துண்டை தர்மம் செய்தாவது நரக நெருப்பிலிருந்து உங்களைக் காத்துக் கொள்ளுங்கள்; அதுவும் இல்லையெனில் ஒரு நல்ல சொல்லின் மூலமாவது தற்காத்துக் கொள்ளுங்கள்.) மேலும் அதே ஸஹீஹில் அதீ (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ﴾«لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ الْمُسْتَسْقِي، وَلَوْ أَنْ تَلْقَى أَخَاكَ وَوَجْهُكَ إِلَيْهِ مُنْـبَسِط»﴿\n\r\n\n\r\n(எந்த ஒரு நற்செயலையும் அற்பமாகக் கருதாதீர்கள். தாகித்திருப்பவரின் பாத்திரத்தில் உமது வாளியிலிருந்து ஒரு முகவை தண்ணீரை ஊற்றுவதாக இருந்தாலும் சரி, அல்லது உமது சகோதரரை மலர்ந்த முகத்துடன் சந்திப்பதாக இருந்தாலும் சரி.) ஸஹீஹில் மேலும் ஒரு ஹதீஸ் பதிவாகியுள்ளது; நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«يَا مَعْشَرَ نِسَاءِ الْمُؤْمِنَاتِ، لَا تَحْقِرَنَّ جَارَةٌ لِجَارَتِهَا وَلَوْ فِرْسَنَ شَاة»﴿\n\r\n\n\r\n(விசுவாசமுள்ள பெண்களே! உங்களில் எவரும் தனது அண்டை வீட்டுப் பெண்ணிற்குக் கொடுப்பதை, அது ஓர் ஆட்டின் குளம்பாக இருந்தாலும் அதனை அற்பமாகக் கருத வேண்டாம்.) 'ஃபிர்ஸன்' என்பது ஆட்டின் குளம்பைக் குறிக்கும். மற்றொரு ஹதீஸில் அவர்கள் கூறினார்கள்: ﴾«رُدُّوا السَّائِلَ وَلَوْ بِظِلْفٍ مُحْرَق»﴿\n\r\n\n\r\n(கேட்பவருக்கு ஏதேனும் கொடுங்கள், அது கருகிய குளம்பாக இருந்தாலும் சரி.) ஆயிஷா (ரழி) அவர்கள் ஒரு திராட்சைப் பழத்தைத் தர்மமாக வழங்கியபோது, \"இது எத்தனை அணுக்களுக்குச் சமமானது தெரியுமா?\" என்று கேட்டதாக அறிவிக்கப்பட்டுள்ளது. இமாம் அஹ்மத் அவர்கள் அவ்ஃப் பின் அல்-ஹாரித் பின் அத்-துஃபைல் வழியாக அறிவிக்கிறார்கள்; ஆயிஷா (ரழி) அவர்கள் கூறியுள்ளார்கள், நபி (ஸல்) அவர்கள் இவ்வாறு கூறுவதுண்டு: ﴾«يَاعَائِشَةُ، إِيَّاكِ وَمُحَقَّرَاتِ الذُّنُوبِ، فَإِنَّ لَهَا مِنَ اللهِ طَالِبًا»﴿\n\r\n\n\r\n(ஆயிஷாவே! அற்பமாகக் கருதப்படும் பாவங்களைக் குறித்து எச்சரிக்கையாக இருங்கள். ஏனெனில், நிச்சயமாக அவற்றைப் பற்றியும் அல்லாஹ்விடம் விசாரணை உண்டு.) இந்த ஹதீஸை அன்-நஸாயீ மற்றும் இப்னு மாஜா ஆகியோரும் பதிவு செய்துள்ளனர். இமாம் அஹ்மத் அவர்கள் அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் வழியாகப் பதிவு செய்துள்ளார்கள்; அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்: ﴾«إِيَّاكُمْ وَمُحَقَّرَاتِ الذُّنُوبِ، فَإِنَّهُنَّ يَجْتَمِعْنَ عَلَى الرَّجُلِ حَتْى يُهْلِكْنَه»﴿\n\r\n\n\r\n(அற்பமாகக் கருதப்படும் பாவங்களைக் குறித்து எச்சரிக்கையாக இருங்கள். ஏனெனில், அவை ஒரு மனிதனிடம் ஒன்று சேர்ந்து அவனைக் கருவறுத்துவிடும்.) இத்தகைய சிறு பாவங்களுக்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஓர் உதாரணமாகக் கூறினார்கள்: வறண்ட நிலத்தில் தங்கும் ஒரு கூட்டத்தைப் போல, அவர்கள் ஒவ்வொருவராகச் சென்று சிறு குச்சிகளைக் கொண்டு வந்து பெரிய சுள்ளிக் குவியலைச் சேர்க்கின்றனர். பிறகு அவர்கள் அதைக் கொண்டு நெருப்பை மூட்டி, அதில் எதைப் போட்டார்களோ அதைச் சமைத்துக் கொள்கிறார்கள். இது சூரா அஸ்-ஸல்ஸலாவின் தஃப்ஸீரின் நிறைவாகும். எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
